package com.android.tools.lint.checks;

import static com.android.tools.lint.detector.api.LintUtils.stripPrefix;
import static com.android.tools.lint.detector.api.SdkConstants.ANDROID_URI;
import static com.android.tools.lint.detector.api.SdkConstants.ATTR_CONTENT_DESCRIPTION;
import static com.android.tools.lint.detector.api.SdkConstants.ATTR_HINT;
import static com.android.tools.lint.detector.api.SdkConstants.ATTR_IMPORTANT_FOR_ACCESSIBILITY;
import static com.android.tools.lint.detector.api.SdkConstants.EDIT_TEXT;
import static com.android.tools.lint.detector.api.SdkConstants.IMAGE_BUTTON;
import static com.android.tools.lint.detector.api.SdkConstants.IMAGE_VIEW;
import static com.android.tools.lint.detector.api.SdkConstants.VALUE_NO;

import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.tools.lint.detector.api.XmlScanner;
import com.google.common.annotations.VisibleForTesting;
import java.util.Arrays;
import java.util.Collection;
import org.jetbrains.annotations.NotNull;
import org.w3c.dom.Element;

public class AccessibilityDetector extends Detector implements XmlScanner {
    private static final Implementation IMPLEMENTATION = new Implementation(
            AccessibilityDetector.class,
            Scope.RESOURCE_FILE_SCOPE);
    public static final Issue ISSUE = Issue.create(
            "ContentDescription",
            "Missing contentDescription attribute on image",
            "Non-textual widgets like ImageViews and ImageButtons should use the `contentDescription` attribute...",
            Category.A11Y,
            3,
            Severity.WARNING,
            IMPLEMENTATION);

    @Override
    public @NotNull Collection<String> getApplicableElements() {
        return Arrays.asList(IMAGE_VIEW, IMAGE_BUTTON, EDIT_TEXT);
    }

    @Override
    public void visitElement(@NotNull XmlContext context, @NotNull Element element) {
        String tag = element.getTagName();
        if (tag.equals(IMAGE_VIEW) || tag.equals(IMAGE_BUTTON)) {
            if (!element.hasAttributeNS(ANDROID_URI, ATTR_CONTENT_DESCRIPTION)) {
                String important = element.getAttributeNS(ANDROID_URI, ATTR_IMPORTANT_FOR_ACCESSIBILITY);
                if (VALUE_NO.equals(important) && context.getMainProject().getMinSdk() >= 16) {
                    return;
                }
                context.report(ISSUE, element, context.getLocation(element),
                        "Missing `contentDescription` attribute on image");
            }
        } else if (tag.equals(EDIT_TEXT)) {
            if (element.hasAttributeNS(ANDROID_URI, ATTR_HINT)
                    && element.hasAttributeNS(ANDROID_URI, ATTR_CONTENT_DESCRIPTION)) {
                context.report(ISSUE, element, context.getLocation(element),
                        "Do not set both `contentDescription` and `hint` on an EditText");
            }
        }
    }
}

